                    const status = (category === 'commitments' || category === 'openLoops') ? ` status=${normalizeStatus(item.status)}` : '';
                    const turnLabel = Number(item.lastTurn || 0) > 0 ? ` turn=${Number(item.lastTurn)}` : '';
                    const refLabel = refs.length ? ` (${refs.join(' ↔ ')})` : '';
