            resolveImportance,
            getRetentionPolicy,
            loadState,
            saveState,
            upsertFromTurn,
            backfillFromMemories,
            enrichCommittedTurn,
            entryRetentionRank,
            isEntryProtected,
            formatForPrompt,
            renameEntityReferences
