                    if (hint.arcKey) bits.push(`arc=${hint.arcKey}`);
                    if (Array.isArray(hint.entityRefs) && hint.entityRefs.length) bits.push(`entities=${hint.entityRefs.slice(0, 5).join('/')}`);
