        strict: Object.freeze({ word: 0.44, char: 0.18, concept: 0.14, lexicalCoverage: 0.18, focus: 0.06, wordCoverageFactor: 0.68, charCoverageFactor: 0.46, conceptCoverageFactor: 0.62 }),
