                            ...(rebuilt.source || {}),
                            rebuildReason: digestMismatch ? 'scope_index_digest_runtime_recall' : 'semantic_graph_v2_runtime_recall',
                            previousSchema: String(graph?.schema || ''),
                            previousVersion: Number(graph?.version || 0) || 0,
