                        enabled: true,
                        schema: HME_SCOPE_INDEX_SCHEMA,
                        mode: 'bounded_pool_bypass',
                        ok: true,
                        sourceCandidates: candidatePool.length,
                        bypassLimit: scopeIndexBypassLimit
