            const storyAuthorPrompt = (memorySuppressionPlan.suppressActiveContext || opaqueTopologyBlocked('storyAuthorPrompt', StoryAuthor.getState?.())) ? '' : redactMainPrompt(StoryAuthor.formatForPrompt?.() || '');
