                UserDlcCore.loadState?.(targetLore, { scopeKey, chatId });
                const allEntities = UserDlcCore.listEntityTargets?.(targetLore) || [];
                const allRelations = UserDlcCore.listRelationTargets?.(targetLore) || [];
                const selected = allEntities
