        overlay.querySelectorAll('[data-udlc-unified-example]').forEach(button => {
            button.addEventListener('click', () => {
                const input = overlay.querySelector('#udlc-unified-request');
                const target = overlay.querySelector('#udlc-unified-target');
                const status = overlay.querySelector('#user-dlc-unified-status');
                if (input) { input.value = button.dataset.udlcUnifiedExample || ''; input.focus(); }
                if (button.dataset.udlcUnifiedKind === 'world' && target) target.value = 'world';
                if (button.dataset.udlcUnifiedKind === 'entity' && target?.value === 'world') {
                    if (status) status.textContent = '인물 또는 관계를 선택하면 해당 LIBRA DB에 연결해 분석합니다.';
                    target.focus();
                }
            });
        });
        overlay.querySelector('#btn-analyze-user-dlc-unified')?.addEventListener('click', () => {
            const request = String(overlay.querySelector('#udlc-unified-request')?.value || '').trim();
            const selected = String(overlay.querySelector('#udlc-unified-target')?.value || 'world');
            const status = overlay.querySelector('#user-dlc-unified-status');
            if (!request) {
                if (status) status.textContent = '추가하거나 분석할 내용을 자연어로 입력해 주세요.';
                overlay.querySelector('#udlc-unified-request')?.focus();
                return;
            }
            const isWorld = selected === 'world';
            const sourceInput = overlay.querySelector(isWorld ? '#udlc-world-request' : '#udlc-entity-request');
            const sourceStatus = overlay.querySelector(isWorld ? '#user-dlc-world-status' : '#user-dlc-entity-status');
            if (!isWorld) {
                overlay.querySelectorAll('[data-udlc-entity-target]').forEach(input => { input.checked = false; });
                const splitAt = selected.indexOf(':');
                const id = splitAt > 0 ? selected.slice(splitAt + 1) : '';
                const targetInput = [...overlay.querySelectorAll('[data-udlc-entity-target]')].find(input => String(input.value || '') === id);
                if (!targetInput) {
                    if (status) status.textContent = '선택한 인물이 현재 DB에서 사라졌습니다. 대상을 다시 선택해 주세요.';
                    refreshUserDlcTargetLists({ preserveSelection: false, announce: false });
                    return;
                }
                targetInput.checked = true;
            }
            if (sourceInput) sourceInput.value = request;
            const initialStatus = String(sourceStatus?.textContent || '');
            if (sourceStatus && status) {
                const observer = new MutationObserver(() => {
                    const next = String(sourceStatus.textContent || '').trim();
                    if (next && next !== initialStatus) status.textContent = next;
                    if (/완료|실패|저장|추가|취소/.test(next)) observer.disconnect();
                });
                observer.observe(sourceStatus, { childList: true, subtree: true, characterData: true });
            }
            if (status) status.textContent = 'LIBRA가 세계관 적응과 저장 위치를 판단하고 있습니다.';
            overlay.querySelector(isWorld ? '#btn-analyze-user-dlc-world' : '#btn-analyze-user-dlc-entity')?.click();
        });
