        overlay.querySelector('#btn-export-settings-file').onclick = async () => {
            try {
                const cfg = buildSettingsConfigFromUI();
                // ★ 감사 P2 — 설정 파일에는 LLM/embedding **API 키**가 들어 있다.
                //   기본은 인증정보 **제외**, 사용자가 명시하면 포함(백업 복원 목적).
                const schema = (typeof LibraSettingsSchema !== 'undefined') ? LibraSettingsSchema : null;
                const hasSecrets = !!(schema && typeof schema.containsSecrets === 'function' && schema.containsSecrets(cfg));
                let payload = cfg;
                if (hasSecrets && schema && typeof schema.stripSecrets === 'function') {
                    const includeSecrets = await Utils.confirmEx([
                        '⚠️ 이 설정 파일에는 API 키 및 인증 정보가 포함될 수 있습니다.',
                        '',
                        '기본은 **인증 정보를 제외**하고 내보냅니다(안전).',
                        '백업을 완전히 복원하려면 인증 정보를 포함해야 합니다.',
                        '',
                        '인증 정보를 **포함**해서 내보낼까요? (취소하면 제외하고 내보냅니다)'
                    ].join('\n'));
                    if (!includeSecrets) payload = schema.stripSecrets(cfg);
                }
                const result = await saveJsonExportFile(payload, `libra-world-maker-settings-${getJsonExportStamp()}.json`);
                toastJsonExportResult('설정 파일', result);
            } catch (e) {
                toast(`❌ 설정 파일 내보내기 실패: ${e?.message || e}`);
            }
        };
